import{_ as o,a,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第一册：英语初阶 · 全册短语与句型 · 第56–83课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-1/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","link":"/life/english/new-concept/book-1/phrases-part-02"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","link":"/life/english/new-concept/book-1/phrases-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","link":"/life/english/new-concept/book-1/phrases-part-02"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","link":"/life/english/new-concept/book-1/phrases-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/phrases-part-03.md","filePath":"life/english/new-concept/book-1/phrases-part-03.md"}'),l={name:"life/english/new-concept/book-1/phrases-part-03.md"};function t(i,e,r,h,u,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-全册短语与句型-·-第56–83课" tabindex="-1">第一册：英语初阶 · 全册短语与句型 · 第56–83课 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型-·-第56–83课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 · 第56–83课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="lesson-56-·-一般现在时的习惯动作" tabindex="-1">Lesson 56 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-56-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 56 · 一般现在时的习惯动作 {#lesson-56-·-一般现在时的习惯动作}&quot;">​</a></h2><ul><li>every morning — 每天早晨</li><li>arrive home — 到家，home 前不加 at</li></ul><p><strong>句型示范：</strong> We usually cook dinner together.</p><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-056">进入本课</a></p><h2 id="lesson-57-·-一般现在时与现在进行时" tabindex="-1">Lesson 57 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-57-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 57 · 一般现在时与现在进行时 {#lesson-57-·-一般现在时与现在进行时}&quot;">​</a></h2><ul><li>usually travel — 描述日常规律</li><li>at the moment — 标明眼前活动</li></ul><p><strong>句型示范：</strong> I usually cycle to work, but today I am taking the bus.</p><p>Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-057">进入本课</a></p><h2 id="lesson-58-·-一般现在时与现在进行时" tabindex="-1">Lesson 58 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-58-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 58 · 一般现在时与现在进行时 {#lesson-58-·-一般现在时与现在进行时}&quot;">​</a></h2><ul><li>usually travel — 描述日常规律</li><li>at the moment — 标明眼前活动</li></ul><p><strong>句型示范：</strong> Leo is wearing a suit now.</p><p>Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-058">进入本课</a></p><h2 id="lesson-59-·-可数和不可数名词的数量" tabindex="-1">Lesson 59 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-59-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 59 · 可数和不可数名词的数量 {#lesson-59-·-可数和不可数名词的数量}&quot;">​</a></h2><ul><li>how many — 问可数数量</li><li>how much — 问不可数数量或价格</li></ul><p><strong>句型示范：</strong> We need five envelopes and some writing paper.</p><p>Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-059">进入本课</a></p><h2 id="lesson-60-·-可数和不可数名词的数量" tabindex="-1">Lesson 60 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-60-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 60 · 可数和不可数名词的数量 {#lesson-60-·-可数和不可数名词的数量}&quot;">​</a></h2><ul><li>how many — 问可数数量</li><li>how much — 问不可数数量或价格</li></ul><p><strong>句型示范：</strong> How much flour do you need?</p><p>How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-060">进入本课</a></p><h2 id="lesson-61-·-have-表身体状况与-must" tabindex="-1">Lesson 61 · have 表身体状况与 must <a class="header-anchor" href="#lesson-61-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 61 · have 表身体状况与 must {#lesson-61-·-have-表身体状况与-must}&quot;">​</a></h2><ul><li>have a headache — have 加名词</li><li>feel tired — feel 加形容词</li></ul><p><strong>句型示范：</strong> Mina has a headache today.</p><p>Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">进入本课</a></p><h2 id="lesson-62-·-have-表身体状况与-must" tabindex="-1">Lesson 62 · have 表身体状况与 must <a class="header-anchor" href="#lesson-62-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 62 · have 表身体状况与 must {#lesson-62-·-have-表身体状况与-must}&quot;">​</a></h2><ul><li>have a headache — have 加名词</li><li>feel tired — feel 加形容词</li></ul><p><strong>句型示范：</strong> What is the matter with him?</p><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-062">进入本课</a></p><h2 id="lesson-63-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 63 · must not 与 do not have to <a class="header-anchor" href="#lesson-63-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 63 · must not 与 do not have to {#lesson-63-·-must-not-与-do-not-have-to}&quot;">​</a></h2><ul><li>must not enter — 禁止进入</li><li>do not have to wait — 不必等候</li></ul><p><strong>句型示范：</strong> You must not make noise in this room.</p><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-063">进入本课</a></p><h2 id="lesson-64-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 64 · must not 与 do not have to <a class="header-anchor" href="#lesson-64-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 64 · must not 与 do not have to {#lesson-64-·-must-not-与-do-not-have-to}&quot;">​</a></h2><ul><li>must not enter — 禁止进入</li><li>do not have to wait — 不必等候</li></ul><p><strong>句型示范：</strong> You do not have to wait outside.</p><p>Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-064">进入本课</a></p><h2 id="lesson-65-·-时间表达与-can-表许可" tabindex="-1">Lesson 65 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-65-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 65 · 时间表达与 can 表许可 {#lesson-65-·-时间表达与-can-表许可}&quot;">​</a></h2><ul><li>can I — 询问许可</li><li>be home by — 不迟于某时到家</li></ul><p><strong>句型示范：</strong> Can I stay until a quarter past nine?</p><p>Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-065">进入本课</a></p><h2 id="lesson-66-·-时间表达与-can-表许可" tabindex="-1">Lesson 66 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-66-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 66 · 时间表达与 can 表许可 {#lesson-66-·-时间表达与-can-表许可}&quot;">​</a></h2><ul><li>can I — 询问许可</li><li>be home by — 不迟于某时到家</li></ul><p><strong>句型示范：</strong> You must be home by half past ten.</p><p>Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-066">进入本课</a></p><h2 id="lesson-67-·-be-的过去式-was-were" tabindex="-1">Lesson 67 · be 的过去式 was/were <a class="header-anchor" href="#lesson-67-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 67 · be 的过去式 was/were {#lesson-67-·-be-的过去式-was-were}&quot;">​</a></h2><ul><li>was at home — 过去在家</li><li>were absent — 过去缺席</li></ul><p><strong>句型示范：</strong> I was at the library last Saturday.</p><p>I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-067">进入本课</a></p><h2 id="lesson-68-·-be-的过去式-was-were" tabindex="-1">Lesson 68 · be 的过去式 was/were <a class="header-anchor" href="#lesson-68-·-be-的过去式-was-were" aria-label="Permalink to &quot;Lesson 68 · be 的过去式 was/were {#lesson-68-·-be-的过去式-was-were}&quot;">​</a></h2><ul><li>was at home — 过去在家</li><li>were absent — 过去缺席</li></ul><p><strong>句型示范：</strong> Were your friends at the concert yesterday?</p><p>Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-068">进入本课</a></p><h2 id="lesson-69-·-过去存在句与时间介词" tabindex="-1">Lesson 69 · 过去存在句与时间介词 <a class="header-anchor" href="#lesson-69-·-过去存在句与时间介词" aria-label="Permalink to &quot;Lesson 69 · 过去存在句与时间介词 {#lesson-69-·-过去存在句与时间介词}&quot;">​</a></h2><ul><li>there were — 过去有多个对象</li><li>on Sunday — 在星期日</li></ul><p><strong>句型示范：</strong> There were hundreds of people at the race.</p><p>There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">进入本课</a></p><h2 id="lesson-70-·-过去存在句与时间介词" tabindex="-1">Lesson 70 · 过去存在句与时间介词 <a class="header-anchor" href="#lesson-70-·-过去存在句与时间介词" aria-label="Permalink to &quot;Lesson 70 · 过去存在句与时间介词 {#lesson-70-·-过去存在句与时间介词}&quot;">​</a></h2><ul><li>there were — 过去有多个对象</li><li>on Sunday — 在星期日</li></ul><p><strong>句型示范：</strong> The final was on Sunday afternoon.</p><p>The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-070">进入本课</a></p><h2 id="lesson-71-·-一般过去时与-did" tabindex="-1">Lesson 71 · 一般过去时与 did <a class="header-anchor" href="#lesson-71-·-一般过去时与-did" aria-label="Permalink to &quot;Lesson 71 · 一般过去时与 did {#lesson-71-·-一般过去时与-did}&quot;">​</a></h2><ul><li>did you call — 询问过去动作</li><li>last night — 昨夜，前面不加介词</li></ul><p><strong>句型示范：</strong> She called the office twice yesterday.</p><p>She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-071">进入本课</a></p><h2 id="lesson-72-·-一般过去时与-did" tabindex="-1">Lesson 72 · 一般过去时与 did <a class="header-anchor" href="#lesson-72-·-一般过去时与-did" aria-label="Permalink to &quot;Lesson 72 · 一般过去时与 did {#lesson-72-·-一般过去时与-did}&quot;">​</a></h2><ul><li>did you call — 询问过去动作</li><li>last night — 昨夜，前面不加介词</li></ul><p><strong>句型示范：</strong> When did you finish the report?</p><p>When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-072">进入本课</a></p><h2 id="lesson-73-·-不规则过去式" tabindex="-1">Lesson 73 · 不规则过去式 <a class="header-anchor" href="#lesson-73-·-不规则过去式" aria-label="Permalink to &quot;Lesson 73 · 不规则过去式 {#lesson-73-·-不规则过去式}&quot;">​</a></h2><ul><li>lose the way — 迷路</li><li>the way to — 到某处的路</li></ul><p><strong>句型示范：</strong> We took the wrong bus and went to the harbour.</p><p>Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-073">进入本课</a></p><h2 id="lesson-74-·-不规则过去式" tabindex="-1">Lesson 74 · 不规则过去式 <a class="header-anchor" href="#lesson-74-·-不规则过去式" aria-label="Permalink to &quot;Lesson 74 · 不规则过去式 {#lesson-74-·-不规则过去式}&quot;">​</a></h2><ul><li>lose the way — 迷路</li><li>the way to — 到某处的路</li></ul><p><strong>句型示范：</strong> Did the guard show you the right road?</p><p>Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-074">进入本课</a></p><h2 id="lesson-75-·-过去时间标记与-buy-bought" tabindex="-1">Lesson 75 · 过去时间标记与 buy/bought <a class="header-anchor" href="#lesson-75-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;Lesson 75 · 过去时间标记与 buy/bought {#lesson-75-·-过去时间标记与-buy-bought}&quot;">​</a></h2><ul><li>a pair of — 一双，pair 可计数</li><li>two days ago — 两天以前</li></ul><p><strong>句型示范：</strong> I bought these boots three weeks ago.</p><p>Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-075">进入本课</a></p><h2 id="lesson-76-·-过去时间标记与-buy-bought" tabindex="-1">Lesson 76 · 过去时间标记与 buy/bought <a class="header-anchor" href="#lesson-76-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;Lesson 76 · 过去时间标记与 buy/bought {#lesson-76-·-过去时间标记与-buy-bought}&quot;">​</a></h2><ul><li>a pair of — 一双，pair 可计数</li><li>two days ago — 两天以前</li></ul><p><strong>句型示范：</strong> Did you wear the new shoes yesterday?</p><p>Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-076">进入本课</a></p><h2 id="lesson-77-·-时间介词与否定疑问句" tabindex="-1">Lesson 77 · 时间介词与否定疑问句 <a class="header-anchor" href="#lesson-77-·-时间介词与否定疑问句" aria-label="Permalink to &quot;Lesson 77 · 时间介词与否定疑问句 {#lesson-77-·-时间介词与否定疑问句}&quot;">​</a></h2><ul><li>at two thirty — 在两点半</li><li>on Tuesday morning — 在星期二早上</li></ul><p><strong>句型示范：</strong> My appointment is at ten on Thursday.</p><p>My appointment 是主语，is 连接时间表语；at ten 表钟点，on Thursday 表某一天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-077">进入本课</a></p><h2 id="lesson-78-·-时间介词与否定疑问句" tabindex="-1">Lesson 78 · 时间介词与否定疑问句 <a class="header-anchor" href="#lesson-78-·-时间介词与否定疑问句" aria-label="Permalink to &quot;Lesson 78 · 时间介词与否定疑问句 {#lesson-78-·-时间介词与否定疑问句}&quot;">​</a></h2><ul><li>at two thirty — 在两点半</li><li>on Tuesday morning — 在星期二早上</li></ul><p><strong>句型示范：</strong> Can you come earlier on Friday?</p><p>Can you 询问是否能够；come 用原形，earlier 是副词比较级，on Friday 交代是哪天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-078">进入本课</a></p><h2 id="lesson-79-·-need-与-must" tabindex="-1">Lesson 79 · need 与 must <a class="header-anchor" href="#lesson-79-·-need-与-must" aria-label="Permalink to &quot;Lesson 79 · need 与 must {#lesson-79-·-need-与-must}&quot;">​</a></h2><ul><li>need to buy — 需要购买</li><li>must go — 必须去，不加 to</li></ul><p><strong>句型示范：</strong> We need to buy rice and tomatoes.</p><p>Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-079">进入本课</a></p><h2 id="lesson-80-·-need-与-must" tabindex="-1">Lesson 80 · need 与 must <a class="header-anchor" href="#lesson-80-·-need-与-must" aria-label="Permalink to &quot;Lesson 80 · need 与 must {#lesson-80-·-need-与-must}&quot;">​</a></h2><ul><li>need to buy — 需要购买</li><li>must go — 必须去，不加 to</li></ul><p><strong>句型示范：</strong> She must go to the pharmacy before six.</p><p>She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-080">进入本课</a></p><h2 id="lesson-81-·-have-had-的活动用法" tabindex="-1">Lesson 81 · have/had 的活动用法 <a class="header-anchor" href="#lesson-81-·-have-had-的活动用法" aria-label="Permalink to &quot;Lesson 81 · have/had 的活动用法 {#lesson-81-·-have-had-的活动用法}&quot;">​</a></h2><ul><li>have lunch — 吃午饭</li><li>have a rest — 休息一下</li></ul><p><strong>句型示范：</strong> We had vegetable soup for lunch.</p><p>Had 是 have 的过去式，此处表示吃喝；vegetable soup 为食物对象，for lunch 表午餐所用。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-081">进入本课</a></p><h2 id="lesson-82-·-have-had-的活动用法" tabindex="-1">Lesson 82 · have/had 的活动用法 <a class="header-anchor" href="#lesson-82-·-have-had-的活动用法" aria-label="Permalink to &quot;Lesson 82 · have/had 的活动用法 {#lesson-82-·-have-had-的活动用法}&quot;">​</a></h2><ul><li>have lunch — 吃午饭</li><li>have a rest — 休息一下</li></ul><p><strong>句型示范：</strong> Did you have a good rest after the journey?</p><p>Did 构成过去问句，have 恢复原形；a good rest 表一次充分休息，after the journey 表先后关系。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-082">进入本课</a></p><h2 id="lesson-83-·-现在完成时入门" tabindex="-1">Lesson 83 · 现在完成时入门 <a class="header-anchor" href="#lesson-83-·-现在完成时入门" aria-label="Permalink to &quot;Lesson 83 · 现在完成时入门 {#lesson-83-·-现在完成时入门}&quot;">​</a></h2><ul><li>have already packed — 已收拾好</li><li>go on holiday — 去度假</li></ul><p><strong>句型示范：</strong> I have already packed my suitcase.</p><p>I have packed 构成现在完成时，already 常放在助动词与分词之间；当前结果是行李已收拾好。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-083">进入本课</a></p>',143)])])}const g=o(l,[["render",t]]);export{c as __pageData,g as default};
